        echo '<section class="zpAdmin20__card"><h2>Dodatkowe obszary</h2><p>Google Ads, Facebook Ads, landing page, pozycjonowanie AI, branding i rebranding. Łączymy rzeczywiste nowe pomiary z zapisanym badaniem ośmiu obszarów. Nie powtarzamy dotychczasowych zapytań. Nowe zapytanie pobiera jedną stronę do 200 wyników, bez dodatkowej paginacji. Wybieramy tylko frazy z wolumenem co najmniej 150 w bazie PL.</p><p><b>Wysłane dodatkowe zapytania: '.(int)$summary['attempted'].'/6.</b> Ta pula nie odnawia się codziennie. Faktyczny limit konta sprawdź w Senuto; żadnej liczby dostępnych kredytów tutaj nie zakładamy.</p>';
        if($summary['base_date'])echo '<p class="zpAdmin20__muted">Pierwsze osiem obszarów: pomiar z '.esc_html($summary['base_date']).'. Zachowujemy oryginalne daty i źródła; wyniki można wykorzystać ponownie bez nowych zapytań.</p>';
        if($summary['state']==='not_started'){self::form('zp_prep_expansion_start');echo '<input type="hidden" name="expansion_market" value="national"><label><input type="checkbox" name="expansion_ack" value="1" required> Potwierdzam najwyżej sześć nowych zapytań Senuto. Badanie nie generuje tekstów ani zdjęć; niepewne żądanie zatrzyma się do sprawdzenia.</label><p><button class="button">Zbadaj dodatkowe obszary</button></p></form>';}
        elseif(in_array($summary['state'],['queued','running'],true))echo '<p>Badanie w toku · zakończono '.(int)$summary['completed'].'/6 obszarów. Odśwież panel, aby odczytać stan.</p>';
        elseif($summary['state']==='needs_attention'){echo '<p>Badanie zatrzymano: '.esc_html($summary['error']).'. Nie ponawiamy niepewnego zapytania. Zapisany wynik odzyskamy bez nowego pobierania.</p>';self::form('zp_prep_expansion_continue');echo '<input type="hidden" name="cohort" value="'.esc_attr($summary['id']).'"><label><input type="checkbox" name="continue_ack" value="1" required> Sprawdziłem stan. Odzyskaj zapisane wyniki; pomiń niepewne żądania i zbadaj tylko niewysłane obszary w limicie sześciu prób.</label><p><button class="button">Wznów bez ponawiania niepewnych zapytań</button></p></form>';}
        $entries=self::state()['entries']??[];if($entries){echo '<details><summary>Odebrane wyniki poszczególnych obszarów</summary><div class="zpAdmin20__tableWrap"><table class="zpAdmin20__table"><thead><tr><th>Obszar</th><th>Odebrane wiersze</th><th>Frazy związane z tematem ≥150</th><th>Data pobrania</th><th>Dalsza strona</th></tr></thead><tbody>';foreach(self::SEEDS as$seed){$e=$entries[$seed['id']]??null;if(!is_array($e))continue;$returned=is_int($e['returned']??null)&&$e['returned']>=0&&$e['returned']<=self::REPORT_LIMIT?(string)$e['returned']:'—';$accepted=empty($e['skipped'])&&is_array($e['rows']??null)&&count($e['rows'])<=self::REPORT_LIMIT?(string)count($e['rows']):'—';$at=is_int($e['retrieved_at']??null)&&$e['retrieved_at']>0?wp_date('Y-m-d',$e['retrieved_at'],new DateTimeZone('Europe/Warsaw')):'—';$next=empty($e['skipped'])&&is_bool($e['has_next_page']??null)?($e['has_next_page']?'Dostępna; nie pobrano':'Brak'):'—';echo '<tr><td>'.esc_html($seed['keyword']).(!empty($e['skipped'])?' · pominięto':'').'</td><td>'.esc_html($returned).'</td><td>'.esc_html($accepted).'</td><td>'.esc_html($at).'</td><td>'.esc_html($next).'</td></tr>';}echo '</tbody></table></div></details>';}
        if($summary['state']==='complete'){
            echo '<p><b>'.count($rows).' aktualnie dostępnych kandydatów z zapisanego zbioru</b> po sprawdzeniu wolumenu, dokładnych powtórek i obecnych rezerwacji. Dobór OpenAI dodatkowo porówna znaczenie tematów, więc ta liczba nie gwarantuje tylu artykułów ani przyszłych zapytań klientów.</p>';
            if($plan){self::form('zp_prep_expansion_articles');foreach(['expansion_start'=>$plan['start'],'expansion_end'=>$plan['end'],'expansion_clock'=>$plan['clock'],'expansion_digest'=>$plan['digest']]as$key=>$value)echo '<input type="hidden" name="'.esc_attr($key).'" value="'.esc_attr($value).'">';echo '<div class="zpAdmin20__grid"><label class="zpAdmin20__field">Artykułów <select name="expansion_count">';foreach([1,2,3,4,5,10]as$n)echo '<option value="'.$n.'">'.$n.'</option>';echo '</select></label><label class="zpAdmin20__field">Odbiorcy <select name="expansion_market"><option value="national">Polska</option><option value="katowice">Katowice</option></select></label></div><p>'.count($plan['dates']).' wolnych terminów do '.esc_html($plan['end']).'.</p><label><input type="checkbox" name="expansion_cost_ack" value="1" required> Użyj zapisanych pomiarów bez nowych zapytań Senuto. Potwierdzam płatny dobór OpenAI, teksty i po trzy zdjęcia (okładkę i dwie odrębne ilustracje). Powstaną szkice do podglądu; publikację zatwierdzę osobno.</label><p><button class="button button-primary"'.(ZP_Content_Auto_Preparation_20261010::busy()||in_array(ZP_Content_Auto_Preparation_20261010::state()['state']??'',['needs_retry'],true)||!$plan['dates']||!$rows?' disabled':'').'>Dobierz tematy z rozszerzonego zbioru</button></p></form>';}
            if($rows){echo '<details><summary>Rzeczywiste frazy, daty i źródła (maks. 250)</summary><div class="zpAdmin20__tableWrap"><table class="zpAdmin20__table"><thead><tr><th>Fraza</th><th>Wolumen PL</th><th>CPC Senuto</th><th>Data i źródło</th></tr></thead><tbody>';foreach(array_slice($rows,0,250)as$r)echo '<tr><td>'.esc_html($r['keyword']).'</td><td>'.(int)$r['volume'].'</td><td>'.(($r['cpc']??null)===null?'—':esc_html((string)$r['cpc'])).'</td><td>'.esc_html($r['date']).'<br>'.esc_html($r['source']).'</td></tr>';echo '</tbody></table></div></details>';}
        }echo '<p class="zpAdmin20__muted">Wolumen jest krajowy PL, również przy odbiorcach z Katowic. Priorytet redakcyjny to związek z usługą i problem klienta; nie jest prognozą konwersji. Źródła zostaną odczytane i sprawdzone przed generacją.</p></section>';
    }
